        for k, v in d.items():
            print(' ' * indent + str(k))
            if isinstance(v, (dict, list)) and indent < 3:
                explore(v, indent + 2)
    elif isinstance(v, list) and len(v) < 10 and indent < 3:
        for item in v[:3]:
            explore(item, indent + 2)

explore(data)
"

