arguments.command:
python3 << 'EOF'
import re

# Let me look for any tables that might have currency exchange information
# in either bulletin
for year in ['1963_12', '1964_12']:
    with open(f'/app/resources/treasury_bulletin_{year}.txt', 'r') as f:
        lines = f.readlines()

    print(f"\n=== {year} - Looking for tables with currency data ===")

    # Look for tables with currency, exchange, rate, etc
    for i, line in enumerate(lines):
        if any(keyword in line.lower() for keyword in ['currency', 'exchange', 'dollar', 'pound']):
            # Get surrounding context
            start = max(0, i-2)
            end = min(len(lines), i+3)
            print(f"\nLine {i}: {line.strip()}")
            for j in range(start, end):
                if j != i:
                    print(f"  {lines[j].strip()[:100]}")
            break
EOF

